### 参考解答

设 `D = a + b - c`。在每一位上，不进位相加的结果是 `(a_i+b_i) mod k`，因此存在非负整数 `M` 使得：

\[
a+b=c+kM
\]

所以，若 `D > 0`，可能的进制 `k` 必须是 `D` 的因子。枚举这些因子，再逐位模拟验证即可。

- `D < 0`：不可能，输出 `0`。
- `D = 0`：对所有 `k > a+b`，`a`、`b` 都是单个数位，且相加不超过 `k-1`，所以结果就是 `a+b=c`；满足条件的 `k` 有无穷多个，输出 `-1`。
- `D > 0`：枚举 `D` 的因子 `k≥2`，检查每位的 `(a % k + b % k) % k` 是否等于 `c % k`，再将三个数都除以 `k` 继续检查。

```cpp
#include <bits/stdc++.h>
using namespace std;

bool valid(long long k, long long a, long long b, long long c) {
    while (a > 0 || b > 0 || c > 0) {
        if ((a % k + b % k) % k != c % k) return false;
        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        long long a, b, c;
        cin >> a >> b >> c;

        long long d = a + b - c;

        if (d < 0) {
            cout << 0 << '\n';
        } else if (d == 0) {
            cout << -1 << '\n';
        } else {
            int answer = 0;
            for (long long i = 1; i * i <= d; ++i) {
                if (d % i != 0) continue;

                long long j = d / i;
                if (i >= 2 && valid(i, a, b, c)) ++answer;
                if (j != i && j >= 2 && valid(j, a, b, c)) ++answer;
            }
            cout << answer << '\n';
        }
    }
    return 0;
}
```

