import { AutocompleteInput } from './AutocompleteInput';

const App: React.FC = () => {
  const fruitOptions = [
    'Apple',
    'Apricot',
    'Avocado',
    'Banana',
    'Blueberry',
    'Cherry',
    'Coconut',
    'Grape',
    'Lemon',
    'Lime',
    'Mango',
    'Orange',
    'Papaya',
    'Peach',
    'Pear',
    'Pineapple',
    'Plum',
    'Strawberry',
    'Watermelon',
    // … imagine thousands more …
  ];

  // Simple validation: non‑empty & at least 3 characters
  const validate = (val: string) => {
    if (val.length < 3) return 'Too short';
    return true;
  };

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Fruit Picker</h2>
      <AutocompleteInput
        options={fruitOptions}
        placeholder="Start typing a fruit..."
        validate={validate}
        onInputChange={(v) => console.log('Current value:', v)}
      />
    </div>
  );
